"""Weekly CFO memo (Phase 6): generated on demand by the agent, cached, never regenerated by viewing."""

from datetime import datetime, timezone
from decimal import Decimal

import pytest
from sqlalchemy import func, select

from app.config import DEFAULT_DEMO_TODAY, get_settings
from app.db.models import CfoMemo, User
from app.services.action_service import ActionService, actor_for
from app.services.llm_budget import LlmBudget
from tests.conftest import ChatHarness
from tests.fakes import ScriptedModel, tool_result


def _memo_text(messages: list[dict]) -> list:
    facts = tool_result(messages, "draft_cfo_memo")["data"]
    cash, low = facts["cash"], facts["lowest_week"]
    return [f"## Cash today\nCash in the bank is {cash['cash_display']} [[{cash['evidence_ids'][0]}]].\n\n"
            f"## The cash gap\n{low['label']} closes at {low['closing_display']} [[{low['ref']}]].\n\n"
            "## Next steps\nApprove or reject what is waiting in the inbox."]


def _scripted() -> ScriptedModel:
    return ScriptedModel([("draft_cfo_memo", {})], _memo_text)


def test_memo_is_generated_once_and_viewing_it_is_free(chat: ChatHarness) -> None:
    chat.model = _scripted()
    owner = chat.login("owner")
    assert chat.client.get("/memo", headers=owner).json() == {"memo": None, "stale": False}

    out = chat.client.post("/memo", headers=owner)
    assert out.status_code == 200, out.text
    memo = out.json()["memo"]
    assert memo["generated_at"] and memo["generated_by"] == "Demo Owner" and memo["as_of"] == "2026-10-01"
    assert "## Cash today" in memo["message"] and memo["warnings"] == []
    assert memo["citations"] and all(c["valid"] for c in memo["citations"])
    assert [r["tools"] for r in chat.model.requests] == [["draft_cfo_memo"], ["draft_cfo_memo"]]
    assert "memo_generated" in chat.events()

    calls = len(chat.model.requests)
    for role in ("owner", "accountant", "viewer"):
        again = chat.client.get("/memo", headers=chat.login(role)).json()
        assert again == {"memo": memo, "stale": False}
    assert len(chat.model.requests) == calls  # viewing never calls the model


def test_memo_turns_cannot_use_other_tools(chat: ChatHarness) -> None:
    chat.model = ScriptedModel([("get_ledger", {"record": "invoices"}), ("draft_cfo_memo", {})], _memo_text)
    out = chat.client.post("/memo", headers=chat.login("owner")).json()
    assert out["memo"]["generated_at"]
    refused = chat.model.requests[1]["messages"][-1]["content"]
    assert refused[0]["is_error"] and "not available in this task" in refused[0]["content"]


def test_memo_turns_out_stale_when_the_facts_change(chat: ChatHarness) -> None:
    chat.model = _scripted()
    owner = chat.login("owner")
    chat.client.post("/memo", headers=owner)
    with chat.factory() as s:
        user = s.scalar(select(User).where(User.email == "owner@emberoak.demo"))
        service = ActionService(s, DEFAULT_DEMO_TODAY)
        draft = service.record_draft(actor_for(user), chat.invoice_id("INV-1042"), "firm")
        service.propose(actor_for(user), "send_reminder", {"invoice_id": draft.params["invoice_id"],
                                                           "draft_id": draft.id}, idempotency_key="memo-stale")
        s.commit()
    assert chat.client.get("/memo", headers=owner).json()["stale"] is True


def test_a_memo_that_fails_the_citation_check_is_shown_but_not_cached(chat: ChatHarness) -> None:
    wrong = ["## Cash today\nCash in the bank is $1,234.56 [[account:1]]."]
    chat.model = ScriptedModel([("draft_cfo_memo", {})], wrong, wrong)
    owner = chat.login("owner")
    out = chat.client.post("/memo", headers=owner).json()["memo"]
    assert out["generated_at"] is None and out["warnings"]
    assert chat.client.get("/memo", headers=owner).json()["memo"] is None
    assert "memo_not_cached" in chat.events()
    with chat.factory() as s:
        assert s.scalar(select(func.count()).select_from(CfoMemo)) == 0


def test_viewer_cannot_generate_and_the_model_is_not_called(chat: ChatHarness) -> None:
    r = chat.client.post("/memo", headers=chat.login("viewer"))
    assert r.status_code == 403 and chat.model.requests == []
    assert chat.events()[-1] == "memo_forbidden"


def test_memo_respects_the_daily_ai_budget(chat: ChatHarness, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(get_settings(), "daily_llm_budget_usd", Decimal("0.05"))
    with chat.factory() as s:
        LlmBudget(s, 0, lambda: datetime.now(timezone.utc)).record("agent", "claude-sonnet-5-5", 25_000, 0)
        s.commit()
    r = chat.client.post("/memo", headers=chat.login("owner"))
    assert r.status_code == 503 and "budget" in r.json()["detail"]
    assert chat.model.requests == []


def test_demo_reset_clears_the_cached_memo(chat: ChatHarness) -> None:
    chat.model = _scripted()
    owner = chat.login("owner")
    chat.client.post("/memo", headers=owner)
    assert chat.client.get("/memo", headers=owner).json()["memo"] is not None
    assert chat.client.post("/demo/reset", headers=owner).json()["removed"]["cfo_memos"] == 1
    assert chat.client.get("/memo", headers=owner).json() == {"memo": None, "stale": False}
    assert chat.client.get("/audit/verify", headers=owner).json()["ok"] is True
